import { promises as fs } from 'fs'
import path from 'path'

const preferencePath = path.join(process.cwd(), 'data', 'notification-preference.json')

export async function getNotificationPreference(): Promise<boolean> {
  try {
    const raw = await fs.readFile(preferencePath, 'utf8')
    const parsed = JSON.parse(raw) as { enabled?: boolean }
    return parsed.enabled === true
  } catch {
    return false
  }
}

export async function setNotificationPreference(enabled: boolean): Promise<boolean> {
  await fs.mkdir(path.dirname(preferencePath), { recursive: true })
  await fs.writeFile(preferencePath, JSON.stringify({ enabled }), 'utf8')
  return enabled
}

